-- Additive administrator-only Preview studio. No member or central records changed.
CREATE TABLE IF NOT EXISTS admin_studio_owners(id TEXT PRIMARY KEY,admin_id TEXT NOT NULL UNIQUE REFERENCES admins(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS admin_personal_worlds(owner_id TEXT NOT NULL REFERENCES admin_studio_owners(id),id TEXT NOT NULL,data TEXT NOT NULL,version INTEGER NOT NULL CHECK(typeof(version)='integer' AND version BETWEEN 1 AND 9007199254740991),last_op_id TEXT NOT NULL,last_op_hash TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id));
CREATE TABLE IF NOT EXISTS admin_personal_world_assets(user_id TEXT NOT NULL REFERENCES admin_studio_owners(id),id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','ready')),file_key TEXT NOT NULL,hash TEXT NOT NULL,metadata TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(user_id,id));
CREATE TABLE IF NOT EXISTS admin_personal_world_revisions(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,world_id TEXT NOT NULL,version INTEGER NOT NULL CHECK(typeof(version)='integer' AND version BETWEEN 1 AND 9007199254740991),data TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(owner_id,world_id) REFERENCES admin_personal_worlds(owner_id,id),UNIQUE(owner_id,world_id,version));
CREATE INDEX IF NOT EXISTS admin_personal_worlds_date ON admin_personal_worlds(owner_id,updated_at);
CREATE TABLE IF NOT EXISTS admin_personal_image_candidates(id TEXT PRIMARY KEY,owner_id TEXT NOT NULL REFERENCES admin_studio_owners(id),world_id TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('pending','candidate','approved','rejected','failed')),asset_id TEXT,request_hash TEXT NOT NULL,data TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(owner_id,world_id) REFERENCES admin_personal_worlds(owner_id,id));
CREATE INDEX IF NOT EXISTS admin_personal_image_world ON admin_personal_image_candidates(owner_id,world_id,created_at);
